from gsl import integrate

def integral(func, a, b, epsabs=1e-6, epsrel=1e-6, workspace_size=1024):
    gsl_function = GSLFunction(func)
    workspace = ctypes.c_void_p()
    CQuadWorkspace.allocate(workspace, workspace_size)

    result, error,neval = integrate.integrate_function(gsl_function, a, b, epsabs, epsrel, workspace)

    return result, error, neval

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def apply(self, x):
        return self.func(x)

class CQuadWorkspace(ctypes.Structure):
    _fields_ = [('size', ctypes.c_int), ('workspace', ctypes.POINTER(ctypes.c_double))]

    @staticmethod
    def allocate(workspace, size):
        CQuadWorkspace.__init__(workspace, size=size)


