import ctypes
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def scale_complex_vector(N, alpha, X, incX):
  x = (ctypes.c_double * N)(*[(complex2double(xi)) for xi in X])
  alpha_ptr = ctypes.cast(ctypes.pointer(alpha), ctypes.POINTER(ctypes.c_double))
  incX_ptr = ctypes.cast(ctypes.pointer(incX), ctypes.POINTER(ctypes.c_int))
  gsl.cblas_zscal(N, alpha_ptr, x, incX_ptr)
  return [double2complex(xi) for xi in x]

def complex2double(z):
  return (z.real, z.imag)

def double2complex(z):
  return complex(z[0], z[1])

