import numpy as np

ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

class GSLMatrix:
  def __init__(self, rows, cols):
    self.matrix = gsl.gsl_matrix_alloc(rows, cols)
  def __del__(self):
    gsl.gsl_matrix_free(self.matrix)
  @property
  def numpy(self):
    return np.frombuffer(gsl.gsl_matrix_data(self.matrix), dtype=np.float64).reshape((self.rows, self.cols))
  @property
  def rows(self):
    return gsl.gsl_matrix_row_size(self.matrix)
  @property
  def cols(self):
    return gsl.gsl_matrix_col_size(self.matrix)

def numpy_to_gsl_matrix(np_array):
  rows, cols = np_array.shape
  matrix = GSLMatrix(rows, cols)
  matrix.numpy[:] = np_array.flatten()
  return matrix
def gsl_matrix_to_numpy(gsl_matrix):
  return gsl_matrix.numpy

def compute_covariance_matrix(jacobian, epsrel, cov_dim):
  jacobian_gsl = numpy_to_gsl_matrix(jacobian)
  cov_gsl = gsl.gsl_multifit_covar(jacobian_gsl, epsrel)
  return gsl_matrix_to_numpy(cov_gsl).reshape((cov_dim, cov_dim))

