class gsl_permutation(ctypes.Structure):
    pass
class gsl_vector(ctypes.Structure):
    pass

gsl_permutation._fields_ = [('size', ctypes.c_int), ('data', ctypes.POINTER(ctypes.c_int))]
gsl_vector._fields_ = [('size', ctypes.c_int), ('stride', ctypes.c_int), ('data', ctypes.POINTER(ctypes.c_double))]

def permute_vector(permutation, vector):
    if len(permutation) != len(vector):
        raise ValueError('Permutation and vector lengths must be equal')
    perm = gsl_permutation(size=len(permutation), data=(_gsl_permutation.from_pylist(permutation))) 
    vec = gsl_vector(size=len(vector), stride=1, data=(_gsl_vector.from_pylist(vector)))
    gsl.permute_vector(perm, vec)
    return [_gsl_vector.to_pylist(vec)]

def _gsl_permutation.from_pylist(lst):
    data = (ctypes.c_int * len(lst))(*lst)
    return data

def _gsl_vector.from_pylist(lst):
    data = (ctypes.c_double * len(lst))(*lst)
    return data

def _gsl_vector.to_pylist(vec):
    return list(vec.data[:vec.size])

