def compute_eigen(matrix, size):
    gsl_matrix_complex.from_list = lambda x: matrix_from_python_list(x)

    m = gsl_matrix_complex(size, size)
    for i in range(size):
        for j in range(size):
            m[i][j] = complex(matrix[i][j][0], matrix[i][j][1])

    workspace = gsl_eigen_hermv_workspace()
