class gsl_qrng_niederreiter(ctypes.Structure):
    _fields_ = [("type", ctypes.c_int),
                  ("state", ctypes.c_void_p)]

def generate_niederreiter_point(dimension: int) -> tuple[float, ...]:
  if not 1 <= dimension <= 12:
    raise ValueError("Dimension must be between 1 and 12")
  qrng = gsl_qrng_niederreiter()
  gsl.gsl_qrng_niederreiter_init(ctypes.cast(qrng, ctypes.POINTER(gsl_qrng_niederreiter)), dimension)
  points = (gsl.gsl_qrng_niederreiter_next(qrng) for _ in range(dimension))
  return tuple(point for point in points)

