import ctypes

ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

def _unpack_B(A):
  class gsl_matrix(ctypes.Structure):
    pass
  class gsl_vector(ctypes.Structure):
    pass
  gsl_linalg_bidiag_unpack_B = gsl.gsl_linalg_bidiag_unpack_B
  A = ctypes.cast(A, gsl_matrix * 1)
  diag = gsl_vector(size=len(A))
  superdiag = gsl_vector(size=len(A) - 1)
  gsl_linalg_bidiag_unpack_B(A, diag, superdiag)
  return [x for x in diag.value], [x for x in superdiag.value]

def extract_diagonal_superdiagonal(A):
  return _unpack_B(A)

