    raise ValueError("Dimension must be between 1 and 1229")
  gsl.gsl_rng_set(gsl.gsl_rng_default)
  result = [[0.0 for _ in range(dimension)] for _ in range(num_points)]
  for i in range(num_points):
    for j in range(dimension):
      result[i][j] = gsl.gsl_qrng_halton(gsl.gsl_rng_default, j + 1)
  return result

