        for i in range(rows):
            for j in range(cols):
                ptr[i * cols + j] = self.data[i][j]
        return ptr

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix: ctypes.c_double *) -> List[List[float]]:
        rows = gsl_matrix.shape[0]
        cols = gsl_matrix.shape[1]
        return [[gsl_matrix[i * cols + j] for j in range(cols)] for i in range(rows)]

