from ctypes import CDLL, c_int, c_double

libgslcblas = CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = CDLL('/usr/local/gsl/lib/libgsl.so')

class gsl_matrix_complex(ctypes.Structure):
    pass

gsl_matrix_complex._fields_ = [
    ('size1', c_int),
    ('size2', c_int),
    ('data', ctypes.POINTER(c_double)) 
]

def call_gsl_linalg_complex_tri_LHL(matrix):
    m = gsl_matrix_complex() 
    m.size1 = matrix.__len__()
    m.size2 = matrix[0].__len__()
    m.data = (c_double * (m.size1 * m.size2))()
    for i in range(m.size1):
        for j in range(m.size2):
            m.data[i * m.size2 + j] = complex(matrix[i][j][0], matrix[i][j][1]).real
    return gsl.gsl_linalg_complex_tri_LHL(c_int(m.size1), c_int(m.size2), m, 0)

def main():
    matrix = [[(1, 2), (3, 4)], [(5, 6), (7, 8)]]
    status, modified_matrix = call_gsl_linalg_complex_tri_LHL(matrix)
    print(f'Status code: {status}')
    print(modified_matrix)

if __name__ == '__main__':
    main()

