    return gsl.gsl_vector_alloc(len(data))

def create_gsl_matrix(data):
    rows, cols = len(data), len(data[0])
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix[i, j] = data[i][j]
    return matrix

