import ctypes
from ctypes import CDLL, c_double, c_voidp
import numpy as np
class GSLFunction:
    def __init__(self, func):
        self.func = func
    def apply(self, x):
        return self.func(x)

def integrate_function(func, a, b):
    libgsl = CDLL('/usr/local/gsl/lib/libgsl.so')
    libcblas = CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl_function = GSLFunction(func)
    result = libgsl.gsl_integration_qk61
    result.restype = c_double
    result.argtypes = [c_voidp, c_double, c_double, c_double]
    return result(gsl_function.apply, a, b, 0)

def compute_integral(func, a, b):
    try:
        integral_result = integrate_function(func, a, b)
        abs_error = abs(integral_result - func(a) * (b-a))
        absolute_value_integral = abs(integral_result)
        square_integral = integrate_function(lambda x: func(x)**2, a, b)
        return {"integral": integral_result, "abs_error": abs_error, "absolute_value_integral": absolute_value_integral, "square_integral": square_integral}
    except Exception as e:
        return {"error": str(e)}

