    b = float(b)

    # Define the function to be integrated
def my_function(x):
    return func(x)

    # Define the GSL integration parameters
    integrand = libgsl.gsl_function_ptr(my_function)
    result = libgsl.gsl_integration_qk61(integrand, a, b)

    integral = result[0]
    error = result[1]
    return integral, error,

def compute_integral(func, a, b):
try:
    integral, error = integrate_function(func, a, b)
    absolute_integral = abs(integral)
    integral_square = integrate_function(lambda x: func(x)**2, a, b)[0]
    return json.dumps({'integral': integral, 'error': error, 'absolute_integral': absolute_integral, 'integral_square': integral_square})
except Exception as e:
    return json.dumps({'error': str(e)})

import ctypes

def compute_weighted_mean(weights, wstride, data, stride):
    try:
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

        weights_ptr = (weights * wstride).ctypes.data_as(ctypes.POINTER(ctypes.c_float))
        data_ptr = (data * stride).ctypes.data_as(ctypes.POINTER(ctypes.c_float))

        wmean = gsl.gsl_stats_wmean(weights_ptr, len(weights) // wstride, data_ptr, len(data) // stride)
        return float(wmean)
    except OSError as e:
        print(f'Error loading library: {e}')
        return None

