import ctypes

def compute_weighted_mean(weights, wstride, data, stride):
    try:
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    except OSError as e:
        raise RuntimeError(f'Failed to load GSL libraries: {e}')

    wmean = gsl.gsl_stats_wmean
    wmean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
    wmean.restype = ctypes.c_double

    return wmean(ctypes.cast(weights, ctypes.POINTER(ctypes.c_double)), wstride, 
