        gsl.gsl_filter_impulse_free(self._workspace)

class GSLVector:
    def __init__(self, data: List[float]):
        self._data = (ctypes.c_float * len(data))(*data)

    def get_data(self) -> List[float]:
        return [d for d in self._data]

class GSLVectorInt:
    def __init__(self, data: List[int]):
        self._data = (ctypes.c_int * len(data))(*data)

    def get_data(self) -> List[int]:
        return [d for d in self._data]

def generate_noisy_signal(N: int, noise_std: float, outlier_prob: float) -> GSLVector:
    import numpy as np
    signal = np.sin(np.linspace(0, 2*np.pi, N))
    noise = np.random.normal(0, noise_std, N)
    outliers = np.random.rand(N) < outlier_prob
outlier_values = np.random.randint(-10, 10, size=N)[outliers]
    signal += noise + outlier_values
    return GSLVector(signal.tolist())

def filter_impulse(workspace: GSLFilterImpulseWorkspace, signal: GSLVector, K: int) -> GSLVector:
    filtered_signal = (ctypes.c_float * len(signal._data))() 
    gsl.gsl_filter_impulse(workspace._workspace, signal._data, len(signal._data), K, filtered_signal)
    return GSLVector(filtered_signal.get_data())

