def bspline_fit(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError("Arrays x and y must have the same length")
    if weights is not None and len(weights) != len(x):
        raise ValueError("Weights array length must match x array length")

x_ptr = gsl_vector(data=ctypes.cast( (ctypes.c_double * len(x))(), ctypes.POINTER(ctypes.c_double)), size=len(x))
    for i in range(len(x)):
        x_ptr.data[i] = x[i]
y_ptr = gsl_vector(data=ctypes.cast((ctypes.c_double * len(y))(), ctypes.POINTER(ctypes.c_double)), size=len(y))
    for i in range(len(y)):
        y_ptr.data[i] = y[i]
    if weights is not None:
        weights_ptr = gsl_vector(data=ctypes.cast((ctypes.c_double * len(weights))(), ctypes.POINTER(ctypes.c_double)), size=len(weights))
        for i in range(len(weights)):
            weights_ptr.data[i] = weights[i]
    else:
        weights_ptr = None

    workspace = gsl.gsl_bspline_workspace_alloc(len(x), 3)
    result = gsl.gsl_bspline_wlssolve(workspace, x_ptr, y_ptr, weights_ptr)
    coefficients = (ctypes.cast(result[0], ctypes.POINTER(ctypes.c_double)))
    chi_squared = result[1]

gsl.gsl_bspline_workspace_free(workspace)
    return list(coefficients[:]), chi_squared

