import ctypes

ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

def next_combination(current_combination: tuple, n: int) -> tuple or None:
    c_current_combination = (ctypes.c_int * len(current_combination))(*current_combination)
    return _next_combination(c_current_combination, n)

def _next_combination(current_combination: ctypes.POINTER(ctypes.c_int), n: int) -> tuple or None:
    result = gsl.gsl_combination_next(current_combination, n)
    if result == 0:
        return None
    return tuple(result[:len(current_combination)])

