import ctypes

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
def compute_eigen_gensymmv(A, B):
    m, n = A.shape
    if m != n or A.shape != B.shape:
        raise ValueError("Matrices must be square and have the same dimensions")
    a = (ctypes.c_double * (m * m))(*A.flatten())
b = (ctypes.c_double * (m * m))(*B.flatten())
    eigen_problem = gsl.gsl_matrix_alloc(m, m)
    for i in range(m):
        for j in range(m):
            eigen_problem[i][j] = a[i * m + j]
    eigen_problem_b = gsl.gsl_matrix_alloc(m, m)
    for i in range(m):
        for j in range(m):
            eigen_problem_b[i][j] = b[i * m + j]
    evals = (ctypes.c_double * m)() 
evecs = gsl.gsl_matrix_alloc(m, m)
    status = gsl.gsl_eigen_gensymmv(eigen_problem, eigen_problem_b, evals, evecs)
    if status != 0:
        raise RuntimeError("Error computing eigenvalues and eigenvectors")
    return evals, (evecs.tolist())

